// V14.8 synthetic resolver showcase only; signed raw HMAC proof is in GitHub Node CI.
const shops={
 A:{tenant:'TENANT_QA_1',store:'STORE_QA_A',name:'Tạp hóa An',sku:'A001',price:159000,stock:3,greeting:'Xin chào! Tiệm An có thể giúp bạn tìm hàng và xem giá nhé.'},
 B:{tenant:'TENANT_QA_1',store:'STORE_QA_B',name:'Thời trang Bình',sku:'A001',price:209000,stock:8,greeting:'Chào bạn, Bình rất vui được tư vấn phong cách phù hợp.'},
 C:{tenant:'TENANT_QA_2',store:'STORE_QA_C',name:'Vật liệu Cường',sku:'A001',price:259000,stock:2,greeting:'Chào anh/chị, Cường hỗ trợ tra mã vật liệu và báo giá.'}
};
const providers={MESSENGER:'meta',ZALO_BOT:'zalo',ZALO_OA:'zalo',WEB_WIDGET:'firstparty'};
return $input.all().map(x=>{
 const f=x.json||{},s=shops[f.shop],p=providers[f.channel];
 const common={...f,identityStatus:'DENIED',route:'DENIED',reason:null,
  tenantId:null,storeId:null,channelBindingId:null,botProfileId:null,
  reply:null,canSend:false,realLlmCalls:0,realMetaZaloSends:0};
 const deny=(reason)=>({json:{...common,reason}});
 if(f.syntheticAuthenticated!==true)return deny('MISSING_SYNTHETIC_PROOF');
 if(!s||!p||f.badAccount)return deny('PRIVATE_BINDING_NOT_FOUND');
 if(f.wrongProvider)return deny('PROVIDER_CHANNEL_MISMATCH');
 if(f.clientStoreId||f.clientTenantId)return deny('CLIENT_SCOPE_OVERRIDE');
 if(f.overriddenStatus==='revoked'||f.expired||f.closed)return deny('REVOKED_EXPIRED_OR_SUSPENDED');
 const base={...common,identityStatus:'RESOLVED',route:'FAST',reason:null,
  tenantId:s.tenant,storeId:s.store,
  channelBindingId:'BINDING_QA_'+f.shop+'_'+f.channel,
  botProfileId:'BOT_QA_'+f.shop+'_'+f.channel};
 if(f.kind==='HELLO')return {json:{...base,reply:'[QA] '+s.greeting}};
 if(f.kind==='QUOTE')return {json:{...base,reply:'[QA] '+s.name+' '+s.sku+': '+s.price+' VND, tồn mẫu '+s.stock,priceVnd:s.price,stock:s.stock}};
 if(f.kind==='ORDER')return {json:{...base,route:'BLOCKED',reason:'NO_ORDER_WRITER_OR_PROVIDER_SEND',reply:null}};
 if(f.kind==='COMPLEX')return {json:{...base,route:'AI_PENDING',reason:'REAL_LLM_NOT_CONNECTED',reply:null}};
 if(f.kind==='WRONG_SKU')return {json:{...common,reason:'SKU_NOT_IN_THIS_SHOP'}};
 if(f.kind==='IDENTITY')return {json:{...base,route:'RESOLVED',reason:'CHANNEL_IDENTITY_SEPARATE',reply:null}};
 return deny('DEFAULT_DENY');
});

